import os
import queue
import threading
from typing import Callable, Optional, Any

import azure.cognitiveservices.speech as speechsdk


class AzureStreamingSpeechToText:
    def __init__(
        self,
        on_partial: Optional[Callable[[str], None]] = None,
        on_final: Optional[Callable[[str], None]] = None,
        language: str = "en-US",
    ):
        self.on_partial = on_partial or (lambda text: None)
        self.on_final = on_final or (lambda text: None)
        self.language = language

        speech_key = os.environ.get("AZURE_SPEECH_KEY")
        speech_region = os.environ.get("AZURE_SPEECH_REGION")
        if not speech_key or not speech_region:
            raise EnvironmentError("AZURE_SPEECH_KEY and AZURE_SPEECH_REGION must be set")

        self.speech_config = speechsdk.SpeechConfig(subscription=speech_key, region=speech_region)
        self.speech_config.speech_recognition_language = self.language

        self._push_stream = speechsdk.audio.PushAudioInputStream()
        audio_config = speechsdk.audio.AudioConfig(stream=self._push_stream)
        self.recognizer = speechsdk.SpeechRecognizer(
            speech_config=self.speech_config,
            audio_config=audio_config,
        )

        self._stop_event = threading.Event()
        self._event_queue: "queue.Queue[tuple[str, str]]" = queue.Queue()
        self._worker_thread: Optional[threading.Thread] = None

        self.recognizer.recognizing.connect(self._handle_recognizing)
        self.recognizer.recognized.connect(self._handle_recognized)
        self.recognizer.canceled.connect(self._handle_canceled)
        self.recognizer.session_stopped.connect(self._handle_session_stopped)

    def _handle_recognizing(self, evt: Any) -> None:
        text = getattr(evt.result, "text", "") or ""
        if text:
            self._event_queue.put(("partial", text))

    def _handle_recognized(self, evt: Any) -> None:
        result = evt.result
        text = getattr(result, "text", "") or ""
        if text:
            self._event_queue.put(("final", text))

    def _handle_canceled(self, evt: Any) -> None:
        reason = getattr(evt, "reason", None)
        details = ""
        if hasattr(evt, "result") and evt.result is not None:
            details = getattr(evt.result, "error_details", "") or ""
        message = f"canceled:{reason}:{details}".strip(":")
        self._event_queue.put(("final", message))

    def _handle_session_stopped(self, evt: Any) -> None:
        self._stop_event.set()

    def _dispatch_events(self) -> None:
        while not self._stop_event.is_set() or not self._event_queue.empty():
            try:
                kind, text = self._event_queue.get(timeout=0.1)
            except queue.Empty:
                continue

            if kind == "partial":
                self.on_partial(text)
            elif kind == "final":
                self.on_final(text)

    def start(self) -> None:
        self._stop_event.clear()
        self.recognizer.start_continuous_recognition()
        self._worker_thread = threading.Thread(target=self._dispatch_events, daemon=True)
        self._worker_thread.start()

    def push_audio(self, pcm16_audio: bytes) -> None:
        if self._stop_event.is_set():
            return
        self._push_stream.write(pcm16_audio)

    def stop(self) -> None:
        try:
            self._push_stream.close()
        finally:
            self.recognizer.stop_continuous_recognition()
            self._stop_event.set()
            if self._worker_thread and self._worker_thread.is_alive():
                self._worker_thread.join(timeout=5)


def stream_recognize_audio(
    audio_chunks: Any,
    on_partial: Optional[Callable[[str], None]] = None,
    on_final: Optional[Callable[[str], None]] = None,
    language: str = "en-US",
) -> AzureStreamingSpeechToText:
    recognizer = AzureStreamingSpeechToText(on_partial=on_partial, on_final=on_final, language=language)
    recognizer.start()
    try:
        for chunk in audio_chunks:
            if not isinstance(chunk, (bytes, bytearray)):
                raise TypeError("audio_chunks must yield PCM16 bytes")
            recognizer.push_audio(bytes(chunk))
    finally:
        recognizer.stop()
    return recognizer
